// Added by AI: Close chatbot when clicking outside
document.addEventListener('click', function(e) {
    var toggle = document.querySelector('#chatbot-container .simple-chatbot #chatbot-toggle');
    var chatbox = document.querySelector('#chatbot-container .simple-chatbot .chatbox');
    if (chatbox && toggle) {
        if (!chatbox.contains(e.target) && !toggle.contains(e.target)) {
            toggle.click();
        }
    }
});
